package com.saleshub.web; import com.saleshub.service.BusinessException; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(BusinessException.class) ResponseEntity<?> business(BusinessException e){return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error","BUSINESS_RULE","message",e.getMessage()));} @ExceptionHandler(Exception.class) ResponseEntity<?> generic(Exception e){return ResponseEntity.status(500).body(Map.of("error","INTERNAL_ERROR","message","Erro interno"));} }
